/****************************************************************************
 * VelaGuard - Device ID module
 *
 * Production: derives device_id from STM32H750B 96-bit Unique ID.
 * Test:       uses compile-time VG_DEVID_OVERRIDE.
 *
 * The STM32H750B UID registers are at 0x1FF1E800 (12 bytes).
 * We produce a hex string "velaguard_" + 24 hex chars from the UID.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "vg_device_id.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* STM32H750B Unique ID base address (96-bit / 12 bytes) */

#define STM32_UID_BASE  0x1ff1e800u
#define STM32_UID_LEN   12

/****************************************************************************
 * Private Data
 ****************************************************************************/

static char g_device_id[VG_DEVICE_ID_MAX_LEN];

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: vg_device_id_init
 *
 * Description:
 *   Initialize the device ID.  Must be called once at startup before any
 *   call to vg_get_device_id().
 *
 *   In test mode (VG_BUILD_MODE=0), uses the compile-time override from
 *   VG_DEVID_OVERRIDE Kconfig.
 *
 *   In production mode (VG_BUILD_MODE=1), reads the 96-bit STM32 UID
 *   and formats it as "velaguard_" + 24 lowercase hex characters.
 ****************************************************************************/

void vg_device_id_init(void)
{
#if CONFIG_VG_BUILD_MODE == 0
  /* Test mode: use compile-time override */

  snprintf(g_device_id, sizeof(g_device_id), "%s",
           CONFIG_VG_DEVID_OVERRIDE);
#else
  /* Production mode: derive from STM32 UID */

  const volatile uint8_t *uid =
    (const volatile uint8_t *)STM32_UID_BASE;
  int i;

  /* Read 12-byte UID and convert to 24-char hex string */

  snprintf(g_device_id, sizeof(g_device_id), "velaguard_");
  for (i = 0; i < STM32_UID_LEN; i++)
    {
      snprintf(g_device_id + 10 + i * 2, 3, "%02x", uid[i]);
    }

  g_device_id[VG_DEVICE_ID_MAX_LEN - 1] = '\0';
#endif
}

/****************************************************************************
 * Name: vg_get_device_id
 *
 * Description:
 *   Returns a pointer to the null-terminated device ID string.
 *   The returned pointer is valid for the lifetime of the process.
 ****************************************************************************/

const char *vg_get_device_id(void)
{
  return g_device_id;
}

/****************************************************************************
 * Name: vg_is_production_build
 *
 * Description:
 *   Returns true if running in production build mode.
 ****************************************************************************/

bool vg_is_production_build(void)
{
#if CONFIG_VG_BUILD_MODE == 1
  return true;
#else
  return false;
#endif
}

/****************************************************************************
 * Name: vg_build_mode_str
 *
 * Description:
 *   Returns "production" or "test".
 ****************************************************************************/

const char *vg_build_mode_str(void)
{
  return vg_is_production_build() ? "production" : "test";
}

/****************************************************************************
 * VelaGuard - Logging module
 *
 * Provides startup logging, data directory initialization, and structured
 * event writing for the VelaGuard gateway.
 *
 * Log style: Log4j2-inspired / Minecraft-like rolling logger.
 * This initial slice creates the directory and writes the startup event.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <time.h>
#include <unistd.h>

#include "vg_device_id.h"
#include "vg_log.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define VG_DATA_DIR       "/data/velaguard"
#define VG_CONFIGS_DIR    "/data/velaguard/configs"
#define VG_LOGS_DIR       "/data/velaguard/logs"
#define VG_EVENTS_FILE    "/data/velaguard/logs/events.jsonl"
#define VG_LOG_FILE       "/data/velaguard/logs/latest.log"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: vg_mkdir_p
 *
 * Description:
 *   Create a directory and all parent directories (like mkdir -p).
 *   Returns 0 on success or if directory already exists.
 ****************************************************************************/

static int vg_mkdir_p(const char *path)
{
  char tmp[128];
  char *p = NULL;
  size_t len;

  snprintf(tmp, sizeof(tmp), "%s", path);
  len = strlen(tmp);

  if (tmp[len - 1] == '/')
    {
      tmp[len - 1] = '\0';
    }

  for (p = tmp + 1; *p; p++)
    {
      if (*p == '/')
        {
          *p = '\0';
          if (mkdir(tmp, 0755) != 0 && errno != EEXIST)
            {
              return -errno;
            }

          *p = '/';
        }
    }

  if (mkdir(tmp, 0755) != 0 && errno != EEXIST)
    {
      return -errno;
    }

  return 0;
}

/****************************************************************************
 * Name: vg_generate_boot_id
 *
 * Description:
 *   Generate a boot ID from the current uptime and device ID.
 *   Format: "{device_id}-boot-{uptime_ms}"
 ****************************************************************************/

static void vg_generate_boot_id(char *buf, size_t buflen)
{
  struct timespec ts;
  uint64_t uptime_ms;
  const char *dev_id = vg_get_device_id();

  clock_gettime(CLOCK_MONOTONIC, &ts);
  uptime_ms = (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;

  snprintf(buf, buflen, "%s-boot-%llu", dev_id,
           (unsigned long long)uptime_ms);
}

/****************************************************************************
 * Name: vg_get_uptime_ms
 *
 * Description:
 *   Get system uptime in milliseconds.
 ****************************************************************************/

static uint64_t vg_get_uptime_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
}

/****************************************************************************
 * Name: vg_get_time_quality
 *
 * Description:
 *   Determine time quality.  For this skeleton, we check if the RTC
 *   has a reasonable year (> 2020).
 ****************************************************************************/

static const char *vg_get_time_quality(void)
{
  time_t now = time(NULL);
  struct tm *tm = gmtime(&now);

  if (tm && tm->tm_year > (2020 - 1900))
    {
      return "rtc";
    }

  return "unknown";
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: vg_log_init
 *
 * Description:
 *   Create the VelaGuard data directory structure and write the
 *   startup log entry and structured event.
 *
 *   Creates:
 *     /data/velaguard/
 *     /data/velaguard/configs/
 *     /data/velaguard/logs/
 *
 *   Writes:
 *     /data/velaguard/logs/latest.log   - human-readable startup log
 *     /data/velaguard/logs/events.jsonl  - structured startup event
 ****************************************************************************/

int vg_log_init(void)
{
  int ret;

  /* Create directory structure */

  ret = vg_mkdir_p(VG_DATA_DIR);
  if (ret < 0)
    {
      fprintf(stderr, "[VelaGuard] Failed to create %s: %s\n",
              VG_DATA_DIR, strerror(-ret));
      return ret;
    }

  ret = vg_mkdir_p(VG_CONFIGS_DIR);
  if (ret < 0)
    {
      fprintf(stderr, "[VelaGuard] Failed to create %s: %s\n",
              VG_CONFIGS_DIR, strerror(-ret));
      return ret;
    }

  ret = vg_mkdir_p(VG_LOGS_DIR);
  if (ret < 0)
    {
      fprintf(stderr, "[VelaGuard] Failed to create %s: %s\n",
              VG_LOGS_DIR, strerror(-ret));
      return ret;
    }

  return 0;
}

/****************************************************************************
 * Name: vg_log_startup_event
 *
 * Description:
 *   Write the startup event.  This must be called after vg_device_id_init()
 *   and vg_log_init().
 *
 *   Writes one human-readable line to latest.log and one JSON line to
 *   events.jsonl.
 ****************************************************************************/

int vg_log_startup_event(void)
{
  const char *dev_id = vg_get_device_id();
  const char *build_mode = vg_build_mode_str();
  const char *version = CONFIG_VG_FIRMWARE_VERSION;
  const char *time_quality = vg_get_time_quality();
  uint64_t uptime_ms = vg_get_uptime_ms();
  char boot_id[VG_DEVICE_ID_MAX_LEN + 32];
  FILE *fp;

  vg_generate_boot_id(boot_id, sizeof(boot_id));

  /* Write human-readable log entry */

  fp = fopen(VG_LOG_FILE, "a");
  if (fp)
    {
      fprintf(fp,
              "[INFO ] [startup] VelaGuard boot | "
              "device_id=%s build_mode=%s version=%s "
              "boot_id=%s uptime_ms=%llu time_quality=%s\n",
              dev_id, build_mode, version, boot_id,
              (unsigned long long)uptime_ms, time_quality);
      fclose(fp);
    }

  /* Write structured JSON event */

  fp = fopen(VG_EVENTS_FILE, "a");
  if (fp)
    {
      fprintf(fp,
              "{\"type\":\"boot\","
              "\"device_id\":\"%s\","
              "\"build_mode\":\"%s\","
              "\"firmware_version\":\"%s\","
              "\"boot_id\":\"%s\","
              "\"uptime_ms\":%llu,"
              "\"time_quality\":\"%s\"}\n",
              dev_id, build_mode, version, boot_id,
              (unsigned long long)uptime_ms, time_quality);
      fclose(fp);
    }

  /* Also print to console for development visibility */

  printf("[VelaGuard] Boot event written:\n");
  printf("  device_id:       %s\n", dev_id);
  printf("  build_mode:      %s\n", build_mode);
  printf("  firmware_version:%s\n", version);
  printf("  boot_id:         %s\n", boot_id);
  printf("  uptime_ms:       %llu\n", (unsigned long long)uptime_ms);
  printf("  time_quality:    %s\n", time_quality);

  return 0;
}

