/****************************************************************************
 * VelaGuard - Home Screen UI (LVGL 9)
 *
 * Displays the VelaGuard home screen with:
 *   - Title bar with build mode indicator
 *   - Device identity: device_id, firmware version
 *   - Status placeholder areas: acquisition, alarm, network, audio, time
 *
 * H750B-DK LCD resolution: 480x272 pixels.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <lvgl/lvgl.h>

#include "vg_device_id.h"
#include "vg_ui_home.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Color scheme - industrial style */

#define VG_COLOR_BG         lv_color_hex(0x1a1a2e)  /* Dark background */
#define VG_COLOR_TITLE_BG   lv_color_hex(0x16213e)  /* Title bar */
#define VG_COLOR_TEXT       lv_color_hex(0xe0e0e0)  /* Light text */
#define VG_COLOR_ACCENT     lv_color_hex(0x0f3460)  /* Accent panels */
#define VG_COLOR_GREEN      lv_color_hex(0x00c853)  /* Normal */
#define VG_COLOR_YELLOW     lv_color_hex(0xffd600)  /* Warning */
#define VG_COLOR_RED        lv_color_hex(0xff1744)  /* Alarm */
#define VG_COLOR_GRAY       lv_color_hex(0x616161)  /* Inactive */
#define VG_COLOR_BLUE       lv_color_hex(0x2979ff)  /* Network/AI */
#define VG_COLOR_CARD_BG    lv_color_hex(0x222244)  /* Card background */

/* Layout constants for 480x272 display */

#define VG_SCREEN_W         480
#define VG_SCREEN_H         272
#define VG_TITLE_H          32
#define VG_INFO_H           36
#define VG_STATUS_AREA_Y    (VG_TITLE_H + VG_INFO_H + 4)
#define VG_STATUS_AREA_H    (VG_SCREEN_H - VG_STATUS_AREA_Y - 4)
#define VG_CARD_COUNT       5
#define VG_CARD_GAP         4
#define VG_CARD_W           ((VG_SCREEN_W - (VG_CARD_COUNT + 1) * VG_CARD_GAP) / VG_CARD_COUNT)

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: vg_create_title_bar
 *
 * Description:
 *   Create the top title bar showing "VelaGuard" and build mode.
 ****************************************************************************/

static lv_obj_t *vg_create_title_bar(lv_obj_t *parent)
{
  lv_obj_t *bar = lv_obj_create(parent);
  lv_obj_set_size(bar, VG_SCREEN_W, VG_TITLE_H);
  lv_obj_align(bar, LV_ALIGN_TOP_LEFT, 0, 0);
  lv_obj_set_style_bg_color(bar, VG_COLOR_TITLE_BG, 0);
  lv_obj_set_style_bg_opa(bar, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(bar, 0, 0);
  lv_obj_set_style_radius(bar, 0, 0);
  lv_obj_set_style_pad_hor(bar, 8, 0);
  lv_obj_set_flex_flow(bar, LV_FLEX_FLOW_ROW);
  lv_obj_set_flex_align(bar, LV_FLEX_ALIGN_SPACE_BETWEEN,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  /* Title label */

  lv_obj_t *title = lv_label_create(bar);
  lv_label_set_text(title, "VelaGuard");
  lv_obj_set_style_text_color(title, VG_COLOR_TEXT, 0);
  lv_obj_set_style_text_font(title, &lv_font_montserrat_16, 0);

  /* Build mode badge */

  lv_obj_t *badge = lv_label_create(bar);
  const char *mode = vg_build_mode_str();
  char mode_buf[32];
  snprintf(mode_buf, sizeof(mode_buf), "[%s]", mode);
  lv_label_set_text(badge, mode_buf);

  if (vg_is_production_build())
    {
      lv_obj_set_style_text_color(badge, VG_COLOR_GREEN, 0);
    }
  else
    {
      lv_obj_set_style_text_color(badge, VG_COLOR_YELLOW, 0);
    }

  lv_obj_set_style_text_font(badge, &lv_font_montserrat_12, 0);

  return bar;
}

/****************************************************************************
 * Name: vg_create_info_row
 *
 * Description:
 *   Create the device info row showing device_id and firmware version.
 ****************************************************************************/

static lv_obj_t *vg_create_info_row(lv_obj_t *parent)
{
  lv_obj_t *row = lv_obj_create(parent);
  lv_obj_set_size(row, VG_SCREEN_W, VG_INFO_H);
  lv_obj_align(row, LV_ALIGN_TOP_LEFT, 0, VG_TITLE_H);
  lv_obj_set_style_bg_color(row, VG_COLOR_BG, 0);
  lv_obj_set_style_bg_opa(row, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(row, 0, 0);
  lv_obj_set_style_radius(row, 0, 0);
  lv_obj_set_style_pad_hor(row, 8, 0);
  lv_obj_set_style_pad_ver(row, 2, 0);
  lv_obj_set_flex_flow(row, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START,
                        LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER);

  /* Device ID line */

  char id_buf[64];
  snprintf(id_buf, sizeof(id_buf), "ID: %s", vg_get_device_id());
  lv_obj_t *id_label = lv_label_create(row);
  lv_label_set_text(id_label, id_buf);
  lv_obj_set_style_text_color(id_label, VG_COLOR_TEXT, 0);
  lv_obj_set_style_text_font(id_label, &lv_font_montserrat_12, 0);

  /* Firmware version line */

  char ver_buf[64];
  snprintf(ver_buf, sizeof(ver_buf), "FW: %s", CONFIG_VG_FIRMWARE_VERSION);
  lv_obj_t *ver_label = lv_label_create(row);
  lv_label_set_text(ver_label, ver_buf);
  lv_obj_set_style_text_color(ver_label, VG_COLOR_GRAY, 0);
  lv_obj_set_style_text_font(ver_label, &lv_font_montserrat_10, 0);

  return row;
}

/****************************************************************************
 * Name: vg_create_status_card
 *
 * Description:
 *   Create a single status card with a label and value placeholder.
 ****************************************************************************/

static lv_obj_t *vg_create_status_card(lv_obj_t *parent, const char *title,
                                        lv_color_t accent_color)
{
  lv_obj_t *card = lv_obj_create(parent);
  lv_obj_set_size(card, VG_CARD_W, VG_STATUS_AREA_H);
  lv_obj_set_style_bg_color(card, VG_COLOR_CARD_BG, 0);
  lv_obj_set_style_bg_opa(card, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(card, 1, 0);
  lv_obj_set_style_border_color(card, accent_color, 0);
  lv_obj_set_style_radius(card, 4, 0);
  lv_obj_set_style_pad_all(card, 4, 0);
  lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(card, LV_FLEX_ALIGN_SPACE_BETWEEN,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  /* Card title */

  lv_obj_t *titleLabel = lv_label_create(card);
  lv_label_set_text(titleLabel, title);
  lv_obj_set_style_text_color(titleLabel, accent_color, 0);
  lv_obj_set_style_text_font(titleLabel, &lv_font_montserrat_10, 0);

  /* Status indicator (dot) */

  lv_obj_t *dot = lv_obj_create(card);
  lv_obj_set_size(dot, 12, 12);
  lv_obj_set_style_bg_color(dot, VG_COLOR_GRAY, 0);
  lv_obj_set_style_bg_opa(dot, LV_OPA_COVER, 0);
  lv_obj_set_style_radius(dot, 6, 0);
  lv_obj_set_style_border_width(dot, 0, 0);

  /* Value placeholder */

  lv_obj_t *value = lv_label_create(card);
  lv_label_set_text(value, "---");
  lv_obj_set_style_text_color(value, VG_COLOR_TEXT, 0);
  lv_obj_set_style_text_font(value, &lv_font_montserrat_12, 0);

  return card;
}

/****************************************************************************
 * Name: vg_create_status_area
 *
 * Description:
 *   Create the status cards row: Acquisition, Alarm, Network, Audio, Time.
 ****************************************************************************/

static void vg_create_status_area(lv_obj_t *parent)
{
  lv_obj_t *area = lv_obj_create(parent);
  lv_obj_set_size(area, VG_SCREEN_W - 8, VG_STATUS_AREA_H);
  lv_obj_align(area, LV_ALIGN_TOP_LEFT, 4, VG_STATUS_AREA_Y);
  lv_obj_set_style_bg_color(area, VG_COLOR_BG, 0);
  lv_obj_set_style_bg_opa(area, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(area, 0, 0);
  lv_obj_set_style_radius(area, 0, 0);
  lv_obj_set_style_pad_all(area, 0, 0);
  lv_obj_set_flex_flow(area, LV_FLEX_FLOW_ROW);
  lv_obj_set_flex_align(area, LV_FLEX_ALIGN_SPACE_EVENLY,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  /* Create 5 status cards */

  vg_create_status_card(area, "Acquire", VG_COLOR_GREEN);
  vg_create_status_card(area, "Alarm", VG_COLOR_RED);
  vg_create_status_card(area, "Network", VG_COLOR_BLUE);
  vg_create_status_card(area, "Audio", VG_COLOR_YELLOW);
  vg_create_status_card(area, "Time", VG_COLOR_GRAY);
}

