/****************************************************************************
 * Name: vg_ui_home_create
 *
 * Description:
 *   Create the VelaGuard home screen on the active LVGL display.
 *   Called once after LVGL and display are initialized.
 ****************************************************************************/

void vg_ui_home_create(void)
{
  lv_obj_t *scr = lv_screen_active();

  /* Set dark background */

  lv_obj_set_style_bg_color(scr, VG_COLOR_BG, 0);
  lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);

  /* Create UI sections */

  vg_create_title_bar(scr);
  vg_create_info_row(scr);
  vg_create_status_area(scr);
}

/****************************************************************************
 * VelaGuard - Main entry point
 *
 * Bootable VelaGuard skeleton for STM32H750B-DK / openvela.
 *
 * Startup sequence:
 *   1. Initialize device ID (STM32 UID or test override)
 *   2. Create /data/velaguard/ directory structure
 *   3. Write startup log and structured event
 *   4. Initialize LVGL and NuttX display/touch drivers
 *   5. Create VelaGuard home screen
 *   6. Enter LVGL event loop (never returns)
 *
 * This establishes the product boundary before Modbus, networking,
 * AI, or OTA are added in subsequent issues.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <unistd.h>
#include <sys/boardctl.h>
#include <lvgl/lvgl.h>

#include "src/vg_device_id.h"
#include "src/vg_log.h"
#include "src/vg_ui_home.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Touch input device path */

#define VG_INPUT_DEVPATH  "/dev/input0"

/* Should we perform board-specific driver initialization? */

#undef NEED_BOARDINIT

#if defined(CONFIG_BOARDCTL) && !defined(CONFIG_NSH_ARCHINIT)
#  define NEED_BOARDINIT 1
#endif

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: velaguard_main
 *
 * Description:
 *   VelaGuard application entry point.
 *
 *   Boots the VelaGuard skeleton: initializes identity, data storage,
 *   logging, LVGL display, and renders the home screen.
 *
 *   This function does not return under normal operation.
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;
  int ret;

  printf("===========================================\n");
  printf("  VelaGuard - Industrial Edge AI Gateway\n");
  printf("===========================================\n");

  /* Step 1: Initialize device ID */

  vg_device_id_init();
  printf("[VG] Device ID: %s\n", vg_get_device_id());
  printf("[VG] Build mode: %s\n", vg_build_mode_str());

  /* Step 2: Create data directory structure */

  ret = vg_log_init();
  if (ret < 0)
    {
      fprintf(stderr, "[VG] WARNING: Data directory init failed: %d\n", ret);
      /* Continue anyway - log files just won't be created */
    }

  /* Step 3: Write startup log and structured event */

  vg_log_startup_event();

  /* Step 4: Initialize LVGL */

  if (lv_is_initialized())
    {
      fprintf(stderr, "[VG] ERROR: LVGL already initialized!\n");
      return -1;
    }

#ifdef NEED_BOARDINIT
  boardctl(BOARDIOC_INIT, 0);
#endif

  lv_init();
  lv_nuttx_dsc_init(&info);

#ifdef CONFIG_LV_USE_NUTTX_LCD
  info.fb_path = "/dev/lcd0";
#endif

#ifdef CONFIG_INPUT_TOUCHSCREEN
  info.input_path = VG_INPUT_DEVPATH;
#endif

  lv_nuttx_init(&info, &result);

  if (result.disp == NULL)
    {
      fprintf(stderr, "[VG] ERROR: LVGL display init failed!\n");
      lv_deinit();
      return 1;
    }

  printf("[VG] LVGL display initialized\n");

  /* Step 5: Create VelaGuard home screen */

  vg_ui_home_create();
  printf("[VG] Home screen created\n");

  printf("[VG] Entering event loop\n");

  /* Step 6: Enter LVGL event loop (never returns) */

  while (1)
    {
      uint32_t idle;
      idle = lv_timer_handler();

      /* Minimum sleep of 1ms */

      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }

  /* Cleanup (unreachable in normal operation) */

  lv_nuttx_deinit(&result);
  lv_deinit();
  return 0;
}
